from __future__ import annotations

import re
import itertools
import numpy as np


class Script:
    def __init__(self, text: str):
        self.text = text
        self.lines = [l.strip() for l in text.splitlines() if l.strip() and not l.startswith("#")]
        self.vars: dict[str, float] = {}
        self.computes: dict[str, dict] = {}
        self.fixes: list[dict] = []
        self.pair_lj: dict[tuple[int, int], tuple[float, float, float]] = {}
        self.model_style = None
        self.e_diff_expr = None
        self.thermo_style = None
        self.n = self.alpha = self.rcut = None
        self.ntypes = 0
        self._parse()

    # ---- expression evaluation (LAMMPS-like) ----
    def _eval(self, expr: str) -> float:
        expr = expr.strip()
        # ${VAR} and v_VAR references
        def sub_curly(m):
            return "(" + repr(self.vars[m.group(1)]) + ")"
        expr = re.sub(r"\$\{(\w+)\}", sub_curly, expr)
        expr = re.sub(r"\bv_(\w+)\b", lambda m: "(" + repr(self.vars[m.group(1)]) + ")", expr)
        return float(eval(expr, {"__builtins__": {}}, {}))

    def _parse(self):
        for line in self.lines:
            tok = line.split()
            cmd = tok[0]
            if cmd == "variable":
                name, kind, rhs = tok[1], tok[2], " ".join(tok[3:])
                assert kind == "equal", line
                if name == "e_diff":
                    self.e_diff_expr = rhs        # keep symbolic: refers to a compute
                else:
                    self.vars[name] = self._eval(rhs)
            elif cmd == "mass":
                self.ntypes = max(self.ntypes, int(tok[1]))
            elif cmd == "pair_style":
                if tok[1] == "hybrid/overlay":
                    rest = tok[2:]
                    if rest[0] == "deepmd":
                        self.model_style, rest = "deepmd", rest[2:]
                    elif rest[0] == "meam":
                        self.model_style, rest = "meam", rest[1:]
                    assert rest[0] == "lj/cut/soft", line
                    self.n, self.alpha, self.rcut = (float(x) for x in rest[1:4])
                else:
                    assert tok[1] == "lj/cut/soft", line
                    self.n, self.alpha, self.rcut = (float(x) for x in tok[2:5])
            elif cmd == "pair_coeff":
                i, j = tok[1], tok[2]
                rest = tok[3:]
                if rest and rest[0] in ("deepmd", "meam"):
                    continue
                if rest and rest[0] == "lj/cut/soft":
                    rest = rest[1:]
                assert i != "*" and j != "*", f"lj pair_coeff must be per pair: {line}"
                self.pair_lj[(int(i), int(j))] = tuple(self._eval(x) for x in rest[:3])
            elif cmd == "fix" and len(tok) > 3 and tok[3] == "adapt/fep":
                t = tok[5:]           # after 'adapt/fep 0'
                assert t[0] == "pair"
                self.fixes.append(
                    dict(pstyle=t[1], param=t[2], I=t[3], J=t[4], var=t[5],
                         scale="scale" in t and t[t.index("scale") + 1] == "yes")
                )
            elif cmd == "compute" and len(tok) > 3 and tok[3] == "fep":
                perts = []
                t = tok[5:]
                while t:
                    assert t[0] == "pair", line
