                self.computes[tok[1]] = dict(kind="fep", temp=self._eval(tok[4]), perts=perts)
            elif cmd == "compute":
                self.computes[tok[1]] = dict(kind=" ".join(tok[3:]))
            elif cmd == "thermo_style":
                self.thermo_style = tok[2:]

    # ---- physics ----
    def _lj_soft_pair(self, r, eps, sigma, act):
        if r >= self.rcut:
            return 0.0
        d = self.alpha * (1.0 - act) ** 2 + (r / sigma) ** 6
        return act ** self.n * 4.0 * eps * (1.0 / d**2 - 1.0 / d)

    def u_lj(self, conf, eps_map):
        pos, types = conf
        u = 0.0
        for a, b in itertools.combinations(range(len(types)), 2):
            i, j = sorted((types[a], types[b]))
            _, sigma, act = self.pair_lj[(i, j)]
            eps = eps_map[(i, j)]
            u += self._lj_soft_pair(float(np.linalg.norm(pos[a] - pos[b])), eps, sigma, act)
        return u

    def eps_base(self):
        return {k: v[0] for k, v in self.pair_lj.items()}

    def _pairs_in_range(self, I, J):
        rng = lambda s: range(1, self.ntypes + 1) if s == "*" else [int(s)]
        out = []
        for i in rng(I):
            for j in rng(J):
                if i <= j and (i, j) in self.pair_lj:
                    out.append((i, j))
