                for p in self._pairs_in_range(f["I"], f["J"]):
                    eps[p] = self.eps_base()[p] * val
            elif f["param"] == "scale":
                model_scale = val
        return eps, model_scale

    def u_total(self, conf, eps, model_scale, u_model):
        return self.u_lj(conf, eps) + model_scale * u_model

    def e_diff(self, conf, u_model):
        """Evaluate the observable exactly the way LAMMPS would."""
        expr = self.e_diff_expr
        m = re.fullmatch(r"c_(\w+)\[(\d+)\]", expr)
        assert m, f"observable must come from a compute, got {expr!r}"
        cid, col = m.group(1), int(m.group(2))
        comp = self.computes[cid]
        assert comp["kind"] == "fep" and col == 1
        eps, model_scale = self.effective_state()
        u0 = self.u_total(conf, eps, model_scale, u_model)
        eps_p, scale_p = dict(eps), model_scale
        for p in comp["perts"]:
            delta = self.vars[p["var"][2:]]
            if p["pstyle"] == "lj/cut/soft" and p["param"] == "epsilon":
                for pair in self._pairs_in_range(p["I"], p["J"]):
                    eps_p[pair] += delta
            elif p["param"] == "scale":
                scale_p += delta
        return self.u_total(conf, eps_p, scale_p, u_model) - u0
