"""Scientific regression tests for the atomic-liquid HTI coupling path.

The soft (reference) interaction of ``dpti.hti_liq`` is coupled to the
Hamiltonian linearly through ``epsilon``.  The quantity written to the
thermodynamic-integration column of the LAMMPS log must therefore be
``dU/dlambda`` of the interaction that is being switched, for *every* point of
the path (including its end points ``lambda = 0`` and ``lambda = 1``) and for
every chemically distinct pair of atom types of a mixture.
"""

import itertools
import os
import re
import sys

import numpy as np
import pytest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

from dpti.hti_liq import _gen_lammps_input_ideal  # noqa: E402

STEPS = ["soft_on", "deep_on", "soft_off"]
LAMBDAS = [0.0, 0.02, 0.5, 0.98, 1.0]


def type_pairs(element_num):
    return [
        (i, j) for i in range(element_num) for j in range(element_num) if i <= j
    ]


def soft_param(element_num, parameterization):
    param = {"n": 1.0, "alpha_lj": 0.5, "rcut": 6.0, "element_num": element_num}
    if parameterization == "shared":
        param.update({"epsilon": 0.03, "sigma": 2.7, "activation": 0.5})
        return param
    for index, (i, j) in enumerate(type_pairs(element_num)):
        param[f"epsilon_{i}_{j}"] = 0.02 + 0.005 * index
        param[f"sigma_{i}_{j}"] = 2.3 + 0.1 * i + 0.05 * j
        param[f"activation_{i}_{j}"] = 0.4 + 0.02 * index
    return param


def generate(step, lamb, element_num=1, parameterization="shared", if_meam=False):
    return _gen_lammps_input_ideal(
        step=step,
        conf_file="conf.lmp",
        mass_map=[118.71 + 10.0 * i for i in range(element_num)],
        lamb=lamb,
        soft_param=soft_param(element_num, parameterization),
        model=None if if_meam else "graph.pb",
        nsteps=1000,
        timestep=0.002,
        ens="nvt",
        temp=400.0,
        thermo_freq=10,
        dump_freq=10,
        if_meam=if_meam,
        meam_model={"library": "lib.meam", "element": "Sn", "potential": "Sn.meam"}
        if if_meam
        else None,
    )


def scalar_variables(script):
    """The ``variable ... equal <number>`` definitions of the script."""
    found = {}
    for name, value in re.findall(r"^variable\s+(\S+)\s+equal\s+(\S+)\s*$", script, re.M):
        try:
            found[name] = float(value)
        except ValueError:
            continue
    return found


def epsilon_perturbations(script):
    """The per-pair epsilon perturbations of the ``compute fep`` observable."""
    match = re.search(r"^compute\s+(\S+)\s+all\s+fep\s+\S+\s+(.*)$", script, re.M)
    assert match, "the observable must be measured by a compute fep command"
    variables = scalar_variables(script)
    perturbations = {}
    clauses = re.findall(
        r"pair\s+lj/cut/soft\s+epsilon\s+(\S+)\s+(\S+)\s+v_(\S+)", match.group(2)
    )
    for itype, jtype, var_name in clauses:
        assert var_name in variables, f"{var_name} is used but never defined"
        key = (int(itype), int(jtype))
        assert key not in perturbations, f"pair {key} perturbed twice"
        perturbations[key] = variables[var_name]
    return perturbations


def lj_cut_soft_energy(script, positions, types, epsilon_scale=1.0):
    """Energy of the soft pair interaction described by the script."""
    style = re.search(r"^pair_style\s+.*lj/cut/soft\s+(\S+)\s+(\S+)\s+(\S+)", script, re.M)
    nn, alpha_lj, rcut = (float(x) for x in style.groups())
    coeff = {}
    for itype, jtype, eps, sigma, act in re.findall(
        r"^pair_coeff\s+(\d+)\s+(\d+)\s+(?:lj/cut/soft\s+)?(\S+)\s+(\S+)\s+(\S+)\s*$",
        script,
        re.M,
    ):
        coeff[(int(itype), int(jtype))] = (float(eps), float(sigma), float(act))
    energy = 0.0
    for a, b in itertools.combinations(range(len(types)), 2):
        pair = tuple(sorted((types[a], types[b])))
        eps, sigma, act = coeff[pair]
        r = float(np.linalg.norm(positions[a] - positions[b]))
        if r >= rcut:
            continue
        denom = alpha_lj * (1.0 - act) ** 2 + (r / sigma) ** 6
        energy += act**nn * 4.0 * (epsilon_scale * eps) * (1.0 / denom**2 - 1.0 / denom)
    return energy


def configuration(element_num, natoms=30, seed=42):
    random = np.random.RandomState(seed)
    return random.uniform(0.0, 10.0, size=(natoms, 3)), random.randint(
        1, element_num + 1, size=natoms
    )


@pytest.mark.parametrize("step,lamb", [("soft_on", 0.0), ("soft_off", 1.0)])
@pytest.mark.parametrize("element_num", [1, 2, 3])
@pytest.mark.parametrize("parameterization", ["shared", "pair_specific"])
def test_observable_is_defined_at_the_path_boundary(
    step, lamb, element_num, parameterization
):
    """The end points of the soft-reference path are ordinary states."""
    script = generate(step, lamb, element_num, parameterization)
    observable = re.search(r"^variable\s+e_diff\s+equal\s+(.*)$", script, re.M)
    assert observable, "the integration observable must be defined"
    expression = observable.group(1)
    # at the boundary the coupling variable vanishes: it must not be a divisor
    assert not re.search(r"/\s*v_(INV_)?LAMBDA", expression), expression
    assert not re.search(r"/\s*\$\{(INV_)?LAMBDA\}", expression), expression


@pytest.mark.parametrize("step", STEPS)
@pytest.mark.parametrize("lamb", LAMBDAS)
@pytest.mark.parametrize("element_num", [1, 2, 3])
@pytest.mark.parametrize("parameterization", ["shared", "pair_specific"])
def test_every_reference_is_defined(step, lamb, element_num, parameterization):
    script = generate(step, lamb, element_num, parameterization)
    variables = set(re.findall(r"^variable\s+(\S+)\s+equal", script, re.M))
    computes = set(re.findall(r"^compute\s+(\S+)\s", script, re.M))
    for reference in re.findall(r"v_(\w+)", script):
        assert reference in variables, f"undefined variable {reference}"
    for reference in re.findall(r"c_(\w+)", script):
        assert reference in computes, f"undefined compute {reference}"


@pytest.mark.parametrize("step,sign", [("soft_on", 1.0), ("soft_off", -1.0)])
@pytest.mark.parametrize("lamb", LAMBDAS)
@pytest.mark.parametrize("element_num", [1, 2, 3])
@pytest.mark.parametrize("parameterization", ["shared", "pair_specific"])
def test_pair_parameters_are_kept_distinct(
    step, sign, lamb, element_num, parameterization
):
    """Each distinct pair is perturbed by its own epsilon, with the path sign."""
    script = generate(step, lamb, element_num, parameterization)
    param = soft_param(element_num, parameterization)
    perturbations = epsilon_perturbations(script)
    assert len(perturbations) == len(type_pairs(element_num))
    for i, j in type_pairs(element_num):
        expected = param.get("epsilon", param.get(f"epsilon_{i}_{j}"))
        assert perturbations[(i + 1, j + 1)] == pytest.approx(sign * expected, rel=1e-5)


@pytest.mark.parametrize("step,sign", [("soft_on", 1.0), ("soft_off", -1.0)])
@pytest.mark.parametrize("lamb", LAMBDAS)
@pytest.mark.parametrize("element_num", [1, 2, 3])
@pytest.mark.parametrize("parameterization", ["shared", "pair_specific"])
def test_observable_equals_du_dlambda(step, sign, lamb, element_num, parameterization):
    """compute fep returns the exact derivative: the energy is linear in epsilon."""
    script = generate(step, lamb, element_num, parameterization)
    positions, types = configuration(element_num)
    coupling = lamb if step == "soft_on" else 1.0 - lamb

    # energy of the soft interaction as it is coupled at this lambda ...
    coupled = lj_cut_soft_energy(script, positions, types, epsilon_scale=coupling)
    # ... and after the perturbation applied by compute fep
    perturbations = epsilon_perturbations(script)
    scales = {pair: coupling + delta for pair, delta in perturbations.items()}
    perturbed = 0.0
    for pair, scale in scales.items():
        # epsilon enters linearly, so a per-pair scale can be applied pairwise
        mask = [t for t in types]
        perturbed += _pair_energy(script, positions, mask, pair, scale)
    coupled_pairwise = sum(
        _pair_energy(script, positions, types, pair, coupling) for pair in scales
    )
    assert coupled == pytest.approx(coupled_pairwise, rel=1e-10, abs=1e-12)

    observable = perturbed - coupled
    reference = sign * lj_cut_soft_energy(script, positions, types, epsilon_scale=1.0)
    assert observable == pytest.approx(reference, rel=1e-9, abs=1e-12)
    assert np.isfinite(observable)


def _pair_energy(script, positions, types, pair, epsilon_scale):
    """Soft-interaction energy of a single (i, j) type pair."""
    itype, jtype = pair
    selected = [
        index for index, t in enumerate(types) if t in (itype, jtype)
    ]
    energy = 0.0
    for a, b in itertools.combinations(selected, 2):
        if tuple(sorted((types[a], types[b]))) != pair:
            continue
        energy += lj_cut_soft_energy(
            script,
            np.array([positions[a], positions[b]]),
            [types[a], types[b]],
            epsilon_scale=epsilon_scale,
        )
    return energy


@pytest.mark.parametrize("step", STEPS)
@pytest.mark.parametrize("if_meam", [False, True])
def test_thermo_column_of_the_observable_is_preserved(step, if_meam):
    """`_post_tasks` reads the observable from column 8 of the LAMMPS log."""
    script = generate(step, 0.5, if_meam=if_meam)
    thermo = re.search(r"^thermo_style\s+custom\s+(.*)$", script, re.M).group(1).split()
    assert thermo.index("v_e_diff") == 8
    assert thermo[-1] == "c_allmsd[*]"
